import{_ as n,o as t,c as s,ag as r}from"./chunks/framework.ySAk_w31.js";const g=JSON.parse(`{"title":"Garder la main","description":"","frontmatter":{},"headers":[],"relativePath":"handout-05-garder-la-main.md","filePath":"handout-05-garder-la-main.md","handout":{"fichier":"handout-05-garder-la-main.md","markdown":"# Handout — Garder la main\\n\\n**Développeur IA — Foundation · Zenika · fiche module 5**\\n\\nCe qui peut mal tourner avec un agent de code, dans l'ordre des slides du module 5 : des coûts qui s'emballent, des données qui fuient. La context window polluée (« Plus n'est pas mieux ») est au module 2.\\n\\n## Coûts : le token se paie\\n\\n_Module 5 · slide « Coûts : le token se paie »_\\n\\nÀ chaque tour, le harness renvoie tout le contexte : dans la trace du module 1, 7 tours de 12 k à 21 k tokens, soit **118 k tokens d'entrée cumulés** pour une tâche simple (chiffres illustratifs). Le **cache** du fournisseur sert le début inchangé du contexte à moindre coût ; changer de modèle ou de MCP en cours de route l'invalide.\\n\\n**5 réflexes**\\n\\n1. **1 tâche = 1 session** : moins d'historique renvoyé.\\n2. **Être précis** : une demande cadrée, moins d'exploration.\\n3. **Couper les MCP inutiles** : chacun pèse dans le contexte.\\n4. **Garder le même modèle** : sinon le **cache** est perdu.\\n5. **Demander du concis** : moins de tokens en sortie.\\n\\n> Le token se paie, en **entrée** comme en **sortie** : le préfixe déjà vu est **renvoyé à chaque tour**.\\n\\n## 5 risques, 5 garde-fous\\n\\n_Module 5 · slide « 5 risques, 5 garde-fous »_\\n\\n| Risque                  | Ce qui arrive                                      | Exemple réel                                            | Garde-fou                     |\\n| ----------------------- | -------------------------------------------------- | ------------------------------------------------------- | ----------------------------- |\\n| **Hallucination**       | une API ou un paquet inventés, mais plausibles     | un paquet inventé par l'IA, publié ensuite par un tiers | tests, typage, relecture      |\\n| **Prompt injection**    | un contenu piégé détourne l'agent                  | une issue publique qui fait fuiter un dépôt privé       | accès de l'agent limités      |\\n| **Fuite de données**    | code, secrets ou données sortent de l'entreprise   | du code propriétaire collé dans un chatbot              | outils validés, pas de secret |\\n| **Action destructrice** | l'agent supprime ou écrase ce qu'il ne fallait pas | une base de production effacée par un agent             | sandbox, humain qui valide    |\\n| **Coûts**               | une consommation qui s'emballe                     | des clés volées, des factures à 5 chiffres              | plafonds, suivi               |\\n\\n- **Prompt injection** : pour le modèle, tout est du texte, donnée et consigne se confondent. L'instruction peut être cachée dans un README, une issue, une page web, une réponse MCP. Aucun garde-fou ne bloque 100 % des injections : l'architecture (permissions, isolation) borne le risque.\\n- **Faux succès** : « tous les tests passent »… après avoir supprimé le test. On relit le diff et les tests.\\n- **Secrets** : jamais de \`.env\`, de jeton ou de mot de passe dans le contexte. Ce qui entre dans la context window part chez le fournisseur du modèle.\\n- **Dépendances** : vérifier qu'un paquet existe **et** qu'il est le bon.\\n\\n## Le trio létal\\n\\n_Module 5 · slide « 5 risques, 5 garde-fous » (encadré)_\\n\\n**Données privées** + **contenu non fiable** + **sortie vers l'extérieur** = exfiltration possible. L'issue piégée coche les trois cases : un agent qui lit les issues publiques, accède au dépôt privé et peut commenter.\\n\\n> **Casser au moins une branche** : pas d'accès au privé, ou pas de droit d'écrire vers l'extérieur.\\n\\nUne consigne « ne lance jamais de commande destructrice » dans les instructions projet n'est qu'une suggestion : la règle vit dans le **harness** (permissions, isolation), pas dans le prompt.\\n\\n## 2 règles d'or\\n\\n_Module 5 · slide « 2 règles d'or »_\\n\\n| Règle                                             | Ce qu'elle couvre                                                                                                                   | Le test                                   |\\n| ------------------------------------------------- | ----------------------------------------------------------------------------------------------------------------------------------- | ----------------------------------------- |\\n| **1. Code et données sensibles : outils validés** | Rien de confidentiel hors des harness et modèles validés par l'entreprise : code client, données de prod, secrets (\`.env\`, jetons). | L'enverriez-vous par email à un inconnu ? |\\n| **2. Un humain valide avant le merge**            | Obligatoire pour ce qui est irréversible : merge, déploiement, migration, push forcé. Le code généré est le vôtre.                  | Qui signe si c'est faux ?                 |\\n\\n- **Shadow AI** : un abonnement personnel n'a pas les garanties d'un compte entreprise (rétention, entraînement sur les données, localisation).\\n- En mission chez un client, ce sont **les règles du client** qui s'appliquent : vérifier avant la première session.\\n- La mention « co-écrit avec l'IA » dans un commit ne transfère aucune responsabilité.\\n\\n> Ces deux règles couvrent l'essentiel des risques : la **fuite** d'un côté, l'**erreur** de l'autre. C'est le **human-in-the-loop**.\\n\\n## À retenir\\n\\n1. **Une tâche, une session.** Jamais de secret dans le contexte.\\n2. Trio létal : **casser une branche**.\\n3. Le token se paie ; les règles de l'entreprise s'appliquent.\\n\\n**Mots-clés** : cache, plafond de dépense, prompt injection, fuite de données, trio létal, shadow AI, human-in-the-loop — voir le glossaire.\\n\\n## Et après ?\\n\\n_Clôture · slide « Et après ? »_\\n\\n| Niveau d'autonomie           | Ce qu'il demande                                      | Où               |\\n| ---------------------------- | ----------------------------------------------------- | ---------------- |\\n| **Observer sans agir**       | une demande cadrée, un plan relu                      | Foundation       |\\n| **Demander à chaque action** | savoir lire ce que l'agent propose                    | Foundation       |\\n| **Agir dans le périmètre**   | tests, un commit par étape, diff relu                 | Foundation       |\\n| **Aller au bout seul**       | un harness configuré, un environnement isolé, un juge | formation Avancé |\\n\\nLa formation **Développeur IA — Avancé** reprend au cran 4 : un dev, plusieurs agents, un système. Économie de l'agent (prompt caching), harness configuré (hooks, sandbox), ingénierie du contexte, spec-driven, patterns agentiques (Plan-and-Execute, GOAP, agent as a judge, best-of-N), et plusieurs agents en parallèle sur des **worktrees**, pilotés depuis un **ADE**. Conseil : pratiquer d'abord les réflexes de la Foundation sur un vrai ticket.\\n"}}`),o={name:"handout-05-garder-la-main.md"};function a(i,e,u,d,l,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<p class="zh-type">fiche module 5</p><h1 id="handout-garder-la-main" tabindex="-1">Garder la main <a class="header-anchor" href="#handout-garder-la-main" aria-label="Permalink to &quot;Handout — Garder la main&quot;">​</a></h1><p>Ce qui peut mal tourner avec un agent de code, dans l’ordre des slides du module 5 : des coûts qui s’emballent, des données qui fuient. La context window polluée (« Plus n’est pas mieux ») est au module 2.</p><h2 id="couts-le-token-se-paie" tabindex="-1">Coûts : le token se paie <a class="header-anchor" href="#couts-le-token-se-paie" aria-label="Permalink to &quot;Coûts : le token se paie&quot;">​</a></h2><p><em>Module 5 · slide « Coûts : le token se paie »</em></p><p>À chaque tour, le harness renvoie tout le contexte : dans la trace du module 1, 7 tours de 12 k à 21 k tokens, soit <strong>118 k tokens d’entrée cumulés</strong> pour une tâche simple (chiffres illustratifs). Le <strong>cache</strong> du fournisseur sert le début inchangé du contexte à moindre coût ; changer de modèle ou de MCP en cours de route l’invalide.</p><p><strong>5 réflexes</strong></p><ol><li><strong>1 tâche = 1 session</strong> : moins d’historique renvoyé.</li><li><strong>Être précis</strong> : une demande cadrée, moins d’exploration.</li><li><strong>Couper les MCP inutiles</strong> : chacun pèse dans le contexte.</li><li><strong>Garder le même modèle</strong> : sinon le <strong>cache</strong> est perdu.</li><li><strong>Demander du concis</strong> : moins de tokens en sortie.</li></ol><blockquote><p>Le token se paie, en <strong>entrée</strong> comme en <strong>sortie</strong> : le préfixe déjà vu est <strong>renvoyé à chaque tour</strong>.</p></blockquote><h2 id="5-risques-5-garde-fous" tabindex="-1">5 risques, 5 garde-fous <a class="header-anchor" href="#5-risques-5-garde-fous" aria-label="Permalink to &quot;5 risques, 5 garde-fous&quot;">​</a></h2><p><em>Module 5 · slide « 5 risques, 5 garde-fous »</em></p><table tabindex="0"><thead><tr><th>Risque</th><th>Ce qui arrive</th><th>Exemple réel</th><th>Garde-fou</th></tr></thead><tbody><tr><td><strong>Hallucination</strong></td><td>une API ou un paquet inventés, mais plausibles</td><td>un paquet inventé par l’IA, publié ensuite par un tiers</td><td>tests, typage, relecture</td></tr><tr><td><strong>Prompt injection</strong></td><td>un contenu piégé détourne l’agent</td><td>une issue publique qui fait fuiter un dépôt privé</td><td>accès de l’agent limités</td></tr><tr><td><strong>Fuite de données</strong></td><td>code, secrets ou données sortent de l’entreprise</td><td>du code propriétaire collé dans un chatbot</td><td>outils validés, pas de secret</td></tr><tr><td><strong>Action destructrice</strong></td><td>l’agent supprime ou écrase ce qu’il ne fallait pas</td><td>une base de production effacée par un agent</td><td>sandbox, humain qui valide</td></tr><tr><td><strong>Coûts</strong></td><td>une consommation qui s’emballe</td><td>des clés volées, des factures à 5 chiffres</td><td>plafonds, suivi</td></tr></tbody></table><ul><li><strong>Prompt injection</strong> : pour le modèle, tout est du texte, donnée et consigne se confondent. L’instruction peut être cachée dans un README, une issue, une page web, une réponse MCP. Aucun garde-fou ne bloque 100 % des injections : l’architecture (permissions, isolation) borne le risque.</li><li><strong>Faux succès</strong> : « tous les tests passent »… après avoir supprimé le test. On relit le diff et les tests.</li><li><strong>Secrets</strong> : jamais de <code>.env</code>, de jeton ou de mot de passe dans le contexte. Ce qui entre dans la context window part chez le fournisseur du modèle.</li><li><strong>Dépendances</strong> : vérifier qu’un paquet existe <strong>et</strong> qu’il est le bon.</li></ul><h2 id="le-trio-letal" tabindex="-1">Le trio létal <a class="header-anchor" href="#le-trio-letal" aria-label="Permalink to &quot;Le trio létal&quot;">​</a></h2><p><em>Module 5 · slide « 5 risques, 5 garde-fous » (encadré)</em></p><p><strong>Données privées</strong> + <strong>contenu non fiable</strong> + <strong>sortie vers l’extérieur</strong> = exfiltration possible. L’issue piégée coche les trois cases : un agent qui lit les issues publiques, accède au dépôt privé et peut commenter.</p><blockquote><p><strong>Casser au moins une branche</strong> : pas d’accès au privé, ou pas de droit d’écrire vers l’extérieur.</p></blockquote><p>Une consigne « ne lance jamais de commande destructrice » dans les instructions projet n’est qu’une suggestion : la règle vit dans le <strong>harness</strong> (permissions, isolation), pas dans le prompt.</p><h2 id="2-regles-d-or" tabindex="-1">2 règles d’or <a class="header-anchor" href="#2-regles-d-or" aria-label="Permalink to &quot;2 règles d&#39;or&quot;">​</a></h2><p><em>Module 5 · slide « 2 règles d’or »</em></p><table tabindex="0"><thead><tr><th>Règle</th><th>Ce qu’elle couvre</th><th>Le test</th></tr></thead><tbody><tr><td><strong>1. Code et données sensibles : outils validés</strong></td><td>Rien de confidentiel hors des harness et modèles validés par l’entreprise : code client, données de prod, secrets (<code>.env</code>, jetons).</td><td>L’enverriez-vous par email à un inconnu ?</td></tr><tr><td><strong>2. Un humain valide avant le merge</strong></td><td>Obligatoire pour ce qui est irréversible : merge, déploiement, migration, push forcé. Le code généré est le vôtre.</td><td>Qui signe si c’est faux ?</td></tr></tbody></table><ul><li><strong>Shadow AI</strong> : un abonnement personnel n’a pas les garanties d’un compte entreprise (rétention, entraînement sur les données, localisation).</li><li>En mission chez un client, ce sont <strong>les règles du client</strong> qui s’appliquent : vérifier avant la première session.</li><li>La mention « co-écrit avec l’IA » dans un commit ne transfère aucune responsabilité.</li></ul><blockquote><p>Ces deux règles couvrent l’essentiel des risques : la <strong>fuite</strong> d’un côté, l’<strong>erreur</strong> de l’autre. C’est le <strong>human-in-the-loop</strong>.</p></blockquote><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li><strong>Une tâche, une session.</strong> Jamais de secret dans le contexte.</li><li>Trio létal : <strong>casser une branche</strong>.</li><li>Le token se paie ; les règles de l’entreprise s’appliquent.</li></ol><p><strong>Mots-clés</strong> : cache, plafond de dépense, prompt injection, fuite de données, trio létal, shadow AI, human-in-the-loop — voir le glossaire.</p><h2 id="et-apres" tabindex="-1">Et après ? <a class="header-anchor" href="#et-apres" aria-label="Permalink to &quot;Et après ?&quot;">​</a></h2><p><em>Clôture · slide « Et après ? »</em></p><table tabindex="0"><thead><tr><th>Niveau d’autonomie</th><th>Ce qu’il demande</th><th>Où</th></tr></thead><tbody><tr><td><strong>Observer sans agir</strong></td><td>une demande cadrée, un plan relu</td><td>Foundation</td></tr><tr><td><strong>Demander à chaque action</strong></td><td>savoir lire ce que l’agent propose</td><td>Foundation</td></tr><tr><td><strong>Agir dans le périmètre</strong></td><td>tests, un commit par étape, diff relu</td><td>Foundation</td></tr><tr><td><strong>Aller au bout seul</strong></td><td>un harness configuré, un environnement isolé, un juge</td><td>formation Avancé</td></tr></tbody></table><p>La formation <strong>Développeur IA — Avancé</strong> reprend au cran 4 : un dev, plusieurs agents, un système. Économie de l’agent (prompt caching), harness configuré (hooks, sandbox), ingénierie du contexte, spec-driven, patterns agentiques (Plan-and-Execute, GOAP, agent as a judge, best-of-N), et plusieurs agents en parallèle sur des <strong>worktrees</strong>, pilotés depuis un <strong>ADE</strong>. Conseil : pratiquer d’abord les réflexes de la Foundation sur un vrai ticket.</p>',30)])])}const m=n(o,[["render",a]]);export{g as __pageData,m as default};
